import {RanchRenderer} from './ranch-renderer.js';
import * as T from 'three';
import {OrbitControls} from '/vendor/OrbitControls.js';
import {GLTFLoader} from '/vendor/loaders/GLTFLoader.js';
export async function showModel(url,options={}){
 const host=document.querySelector('#scene'),scene=new T.Scene();scene.background=new T.Color('#bdc1b6');
 const camera=new T.PerspectiveCamera(35,1,.1,1000),renderer=new RanchRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=options.exposure??1.15;host.append(renderer.domElement);renderer.domElement.setAttribute('aria-label','Interactive set diorama');renderer.domElement.tabIndex=0;
 scene.add(new T.HemisphereLight(0xfff5df,0x687361,2.2));const sun=new T.DirectionalLight(0xfff3da,3);sun.position.set(-25,45,30);scene.add(sun);if(options.shadows){renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);Object.assign(sun.shadow.camera,{left:-32,right:32,top:32,bottom:-32,near:1,far:120});sun.shadow.normalBias=.08;}
 const model=(await new GLTFLoader().loadAsync(url)).scene;scene.add(model);if(options.shadows)model.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;}});const box=new T.Box3().setFromObject(model),center=box.getCenter(new T.Vector3()),size=box.getSize(new T.Vector3()),radius=size.length()/2;
 const controls=new OrbitControls(camera,renderer.domElement);controls.target.copy(center);controls.enableDamping=true;controls.maxPolarAngle=Math.PI*.49;controls.minDistance=radius*(options.views?.length ? .12 : .5);controls.maxDistance=radius*6;
 function home(){const direction=new T.Vector3(36,43,49).normalize();camera.position.copy(center).add(direction);camera.lookAt(center);const inverse=camera.quaternion.clone().invert(),vertical=Math.tan(T.MathUtils.degToRad(camera.fov/2)),horizontal=vertical*host.clientWidth/host.clientHeight;let distance=0;for(const x of [box.min.x,box.max.x])for(const y of [box.min.y,box.max.y])for(const z of [box.min.z,box.max.z]){const v=new T.Vector3(x,y,z).sub(center).applyQuaternion(inverse);distance=Math.max(distance,v.z+Math.abs(v.x)/horizontal,v.z+Math.abs(v.y)/vertical);}camera.position.copy(center).addScaledVector(direction,distance*.94);controls.target.copy(center);controls.update();}
 function resize(){renderer.setSize(host.clientWidth,host.clientHeight);camera.aspect=host.clientWidth/host.clientHeight;camera.updateProjectionMatrix();home();}new ResizeObserver(resize).observe(host);resize();
 document.querySelector('#home-view').onclick=home;document.querySelector('#turn-view').onclick=()=>{const d=camera.position.clone().sub(controls.target).applyAxisAngle(new T.Vector3(0,1,0),Math.PI/6);camera.position.copy(controls.target).add(d);controls.update();};document.querySelector('#zoom-view').onclick=()=>{camera.position.lerp(controls.target,.18);controls.update();};
 renderer.setAnimationLoop(()=>{controls.update();renderer.render(scene,camera);});
 renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();document.querySelector('.scene-frame').classList.remove('ready');document.querySelector('#scene-status').textContent='Graphics paused · preview shown';});
 return {focus(view){const target=new T.Vector3(...view.target),direction=new T.Vector3(31,40,45).normalize();controls.target.copy(target);camera.position.copy(target).addScaledVector(direction,view.distance);controls.update();},home};
}
